{
  "review_id": "ccr-COMM-90001-2026-07-16-0001",
  "comm_id": "COMM-90001",
  "as_of": "2026-07-16",
  "config_version": "comms-cfg-2026.07",
  "classification": "retail communication",
  "findings": [
    {
      "finding_type": "prohibited_claim",
      "rule": "FINRA Rule 2210(d)(1)",
      "severity": "high",
      "reason": "communication contains prohibited promissory, guarantee, or 'no-risk' language",
      "evidence": [
        {
          "quote": "guaranteed",
          "issue": "guarantee of performance or return",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "guaranteed 12%",
          "issue": "guaranteed specific return",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "risk-free",
          "issue": "'risk-free' claim",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "no risk",
          "issue": "'no risk' claim",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "cannot lose",
          "issue": "'cannot lose money' claim",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        }
      ],
      "remediation": "Remove or substantiate; guarantees, 'risk-free', and 'cannot-lose' claims are prohibited."
    },
    {
      "finding_type": "performance_prediction",
      "rule": "FINRA Rule 2210(d)(1)(F)",
      "severity": "high",
      "reason": "communication predicts or projects future investment performance",
      "evidence": [
        {
          "quote": "we predict",
          "issue": "prediction of future performance",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "will double",
          "issue": "prediction of future performance",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        }
      ],
      "remediation": "Remove predictions/projections of performance or limit to permitted projection use with basis and disclosures."
    },
    {
      "finding_type": "fair_and_balanced",
      "rule": "FINRA Rule 2210(d)(1)(A)",
      "severity": "medium",
      "reason": "benefits/returns are described without a corresponding risk disclosure (one-sided)",
      "evidence": [
        {
          "quote": "fortune, fortunes, return",
          "issue": "no risk_disclosure tag present",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        }
      ],
      "remediation": "Add balanced discussion of material risks and a risk disclosure."
    },
    {
      "finding_type": "missing_required_disclosure",
      "rule": "FINRA Rule 2210(d)",
      "severity": "medium",
      "reason": "one or more required disclosures for this communication class are absent",
      "evidence": [
        {
          "quote": "firm/member name disclosure",
          "issue": "member identity not disclosed",
          "location": "disclosures",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "past-performance disclaimer",
          "issue": "performance discussed without disclaimer",
          "location": "disclosures",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "BrokerCheck reference",
          "issue": "retail website/social without BrokerCheck reference",
          "location": "disclosures",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        },
        {
          "quote": "testimonial disclosures",
          "issue": "testimonial without required disclosures",
          "location": "body",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        }
      ],
      "remediation": "Add each missing required disclosure before the communication is used."
    },
    {
      "finding_type": "supervision_gap",
      "rule": "FINRA Rule 2210(b)(1) / Rule 3110",
      "severity": "high",
      "reason": "retail communication has no registered-principal pre-approval before first use",
      "evidence": [
        {
          "quote": "principal_pre_approved=False",
          "issue": "no principal pre-approval on record",
          "location": "supervision",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        }
      ],
      "remediation": "Obtain registered-principal (e.g., Series 24/26) pre-approval before first use."
    },
    {
      "finding_type": "retention_gap",
      "rule": "SEC Rule 17a-4 / FINRA Rule 4511",
      "severity": "medium",
      "reason": "communication is not recorded as archived in an approved retention system",
      "evidence": [
        {
          "quote": "archived=False",
          "issue": "not archived",
          "location": "retention",
          "citation": "comm:comm=COMM-90001;sys=comm-archive@2026-07-16"
        }
      ],
      "remediation": "Confirm the communication is captured and retained in the approved archive."
    }
  ],
  "fired_finding_types": [
    "fair_and_balanced",
    "missing_required_disclosure",
    "performance_prediction",
    "prohibited_claim",
    "retention_gap",
    "supervision_gap"
  ],
  "recommended_disposition": "Escalate",
  "escalation_routes": [],
  "remediation_prompts": [
    "Remove or substantiate; guarantees, 'risk-free', and 'cannot-lose' claims are prohibited.",
    "Remove predictions/projections of performance or limit to permitted projection use with basis and disclosures.",
    "Add balanced discussion of material risks and a risk disclosure.",
    "Add each missing required disclosure before the communication is used.",
    "Obtain registered-principal (e.g., Series 24/26) pre-approval before first use.",
    "Confirm the communication is captured and retained in the approved archive."
  ],
  "disclaimer": "Advisory compliance review only; not a supervisory approval, regulated determination, or filing. A registered principal must independently review and adjudicate this communication before any use, distribution, regulatory filing, or review closure."
